      "searchText": "Phase-contrast microscopy is based on the principle that light changes its speed when passing through cellular and extracellular structures with different Introduction & Microscopy المدخل والمجهر Phase-contrast microscopy is based on the principle that light changes its speed when passing through cellular and extracellular structures with different refractive indices. These changes are used by the phase-contrast system to cause the structures to appear lighter or darker in relation to each other. Because they allow the examination of cells without fixation or staining, phase contrast microscopes are prominent tools in all cell culture laboratories."
