      "searchText": "Polarizing Microscopy allows the recognition of stained or unstained structures made of highly organized subunits. When normal light passes through Introduction & Microscopy المدخل والمجهر Polarizing Microscopy allows the recognition of stained or unstained structures made of highly organized subunits. When normal light passes through a polarizing filter, it exits vibrating in only one direction. If a second filter is placed in the microscope above the first one, with its main axis perpendicular to the first filter, no light passes through. If tissue structures containing oriented macromolecules are located between the two polarizing filters, their repetitive structure rotates the axis of the light emerging from the polarizer and they appear as bright structures against a dark background . The ability to rotate the direction of vibration of polarized light is called birefringence"
