      "searchText": "C. Periosteum & Endosteum All bones except at joint surfaces are covered both at the external and internal surfaces with a layer formed of vascular C.T. and bone forming cells. Bone, Ossification & Joints العظم والتعظم والمفاصل C. Periosteum & Endosteum All bones except at joint surfaces are covered both at the external and internal surfaces with a layer formed of vascular C.T. and bone forming cells. a) The periosteum It is the vascular non -calcified C.T. sheath covering the bone outer surfaces . It consists of : 1. Outer fibrous layer :a layer of dense collagenous C.T. , of collagen fibers & fibroblasts . It is very rich in blood vessels , which will penetrate to inside the bone . 2. Inner osteogenic (cellular ) layer : It is more cellular ,formed of closely arranged osteogenic cells , which can divide and differentiate into osteoblasts , which are also seen in this layer ."
